PARAMS = {
    "Lc":  (4.0, 1.0, 10.0),    # core channel length (limits crowbar/feedback current)
    "Wn":  (0.5, 0.42, 2.0),    # nfet main-stack width
    "rn":  (1.6, 0.6, 5.0),     # Wnf/Wn  -> raises vth_hi
    "Wp":  (1.5, 0.42, 6.0),    # pfet main-stack width
    "rp":  (0.4, 0.1, 2.0),     # Wpf/Wp  -> lowers vth_lo
    "Wo":  (0.42, 0.42, 2.0),   # buffer inverter nfet width (pfet = 2.4x)
}

VDD = 1.8

def _bisect(f, lo, hi, it=40):
    flo = f(lo)
    for _ in range(it):
        mid = 0.5 * (lo + hi)
        fm = f(mid)
        if (fm > 0) == (flo > 0):
            lo, flo = mid, fm
        else:
            hi = mid
    return 0.5 * (lo + hi)

def design(p, lut, spec):
    Lc = p["Lc"]
    Wn = p["Wn"]; Wnf = max(0.42, p["rn"] * Wn)
    Wp = p["Wp"]; Wpf = max(0.42, p["rp"] * Wp)
    Wo = p["Wo"]; Wop = 2.4 * Wo

    n = Netlist("vin vout vdd vss")
    # PMOS main stack: vdd - M1 - y - M2 - xo
    n.M("M1", "y", "vin", "vdd", "vdd", "pfet", Wp, Lc)
    n.M("M2", "xo", "vin", "y", "vdd", "pfet", Wp, Lc)
    # NMOS main stack: xo - M4 - x - M5 - vss
    n.M("M4", "xo", "vin", "x", "vss", "nfet", Wn, Lc)
    n.M("M5", "x", "vin", "vss", "vss", "nfet", Wn, Lc)
    # feedback devices (gate = core node xo)
    n.M("M3", "vdd", "xo", "x", "vss", "nfet", Wnf, Lc)   # pulls x up -> raises vth_hi
    n.M("M6", "vss", "xo", "y", "vdd", "pfet", Wpf, Lc)   # pulls y down -> lowers vth_lo
    # buffer inverter -> non-inverting overall
    n.M("M7", "vout", "xo", "vss", "vss", "nfet", Wo, 0.15)
    n.M("M8", "vout", "xo", "vdd", "vdd", "pfet", Wop, 0.15)

    vth_hi = 1.3; vth_lo = 0.5; i_avg = 1e-6
    try:
        def vx_of(vi):
            def f(vx):
                i3 = lut.op("n", Wnf, Lc, VDD - vx, VDD - vx, vx)["Id"]
                i5 = lut.op("n", Wn, Lc, vi, max(vx, 1e-3))["Id"]
                return i3 - i5
            return _bisect(f, 1e-3, VDD - 0.3)
        def g_hi(vi):
            vx = vx_of(vi)
            vt4 = lut.op("n", Wn, Lc, max(vi - vx, 0.01), 0.3, vx)["vth"]
            return (vi - vx) - vt4
        vth_hi = _bisect(g_hi, 0.65, VDD)

        def vy_of(vi):
            def f(vy):
                i1 = lut.op("p", Wp, Lc, VDD - vi, max(VDD - vy, 1e-3))["Id"]
                i6 = lut.op("p", Wpf, Lc, vy, vy, VDD - vy)["Id"]
                return i6 - i1
            return _bisect(f, 0.3, VDD - 1e-3)
        def g_lo(vi):
            vy = vy_of(vi)
            vt2 = lut.op("p", Wp, Lc, max(vy - vi, 0.01), 0.3, VDD - vy)["vth"]
            return vt2 - (vy - vi)
        vth_lo = _bisect(g_lo, 0.0, 1.1)

        vs = np.linspace(0.0, VDD, 37)
        acc = 0.0
        for v in vs:
            if v < vth_hi and v > 0.5:
                vx = vx_of(v)
                acc += lut.op("n", Wnf, Lc, VDD - vx, VDD - vx, vx)["Id"]
            if v > vth_lo and v < 1.3:
                vy = vy_of(v)
                acc += lut.op("p", Wpf, Lc, vy, vy, VDD - vy)["Id"]
        i_avg = acc / (2 * len(vs))
    except Exception:
        pass

    return n, {"vth_hi": vth_hi, "vth_lo": vth_lo,
               "hysteresis": vth_hi - vth_lo,
               "power_avg": VDD * i_avg * 1.3,
               "voh": VDD, "vol": 0.0}
